'use strict';

const { contextBridge, ipcRenderer } = require('electron');

// Открываем безопасное API для renderer-процесса
contextBridge.exposeInMainWorld('crmApp', {
  // Навигация по CRM
  navigate: (path) => ipcRenderer.send('navigate', path),
  // Версия приложения
  version: process.env.npm_package_version || '1.0.0',
});

// API для управления стилями
contextBridge.exposeInMainWorld('desktopAPI', {
  applyStyles: (styleSettings) => {
    if (!styleSettings) return;

    // Применяем тему
    const theme = styleSettings.appTheme || 'auto';
    if (theme === 'light') {
      document.documentElement.removeAttribute('data-theme');
      document.documentElement.style.colorScheme = 'light';
    } else if (theme === 'dark') {
      document.documentElement.setAttribute('data-theme', 'dark');
      document.documentElement.style.colorScheme = 'dark';
    } else if (theme === 'auto') {
      document.documentElement.removeAttribute('data-theme');
      document.documentElement.style.colorScheme = 'normal';
    }

    // Применяем размер шрифта
    const fontSize = styleSettings.fontSize || 'normal';
    const fontSizeMap = {
      small: '12px',
      normal: '14px',
      large: '16px',
      xlarge: '18px'
    };
    document.documentElement.style.fontSize = fontSizeMap[fontSize] || '14px';

    // Применяем высокий контраст
    if (styleSettings.highContrast) {
      document.documentElement.setAttribute('data-high-contrast', 'true');
    } else {
      document.documentElement.removeAttribute('data-high-contrast');
    }

    // Применяем сокращение анимаций
    if (styleSettings.reduceAnimations) {
      document.documentElement.setAttribute('data-reduce-animations', 'true');
    } else {
      document.documentElement.removeAttribute('data-reduce-animations');
    }
  }
});

window.addEventListener('DOMContentLoaded', () => {
  // Добавляем класс, что запущено в Electron
  document.documentElement.classList.add('electron-app');

  // Показываем версию в title если не задана
  if (!document.title) {
    document.title = 'FixByte CRM';
  }
});

'use strict';

const { contextBridge, ipcRenderer } = require('electron');

// Открываем безопасное API для renderer-процесса
contextBridge.exposeInMainWorld('crmApp', {
  // Навигация по CRM
  navigate: (path) => ipcRenderer.send('navigate', path),
  // Версия приложения
  version: process.env.npm_package_version || '1.0.0',
});

// API для управления стилями
contextBridge.exposeInMainWorld('desktopAPI', {
  applyStyles: (styleSettings) => {
    if (!styleSettings) return;

    // Применяем тему
    const theme = styleSettings.appTheme || 'auto';
    if (theme === 'light') {
      document.documentElement.removeAttribute('data-theme');
      document.documentElement.style.colorScheme = 'light';
    } else if (theme === 'dark') {
      document.documentElement.setAttribute('data-theme', 'dark');
      document.documentElement.style.colorScheme = 'dark';
    } else if (theme === 'auto') {
      document.documentElement.removeAttribute('data-theme');
      document.documentElement.style.colorScheme = 'normal';
    }

    // Применяем размер шрифта
    const fontSize = styleSettings.fontSize || 'normal';
    const fontSizeMap = {
      small: '12px',
      normal: '14px',
      large: '16px',
      xlarge: '18px'
    };
    document.documentElement.style.fontSize = fontSizeMap[fontSize] || '14px';

    // Применяем высокий контраст
    if (styleSettings.highContrast) {
      document.documentElement.setAttribute('data-high-contrast', 'true');
    } else {
      document.documentElement.removeAttribute('data-high-contrast');
    }

    // Применяем сокращение анимаций
    if (styleSettings.reduceAnimations) {
      document.documentElement.setAttribute('data-reduce-animations', 'true');
    } else {
      document.documentElement.removeAttribute('data-reduce-animations');
    }

    // Применяем стиль рамки
    const frameStyle = styleSettings.frameStyle || 'native';
    document.documentElement.setAttribute('data-frame-style', frameStyle);

    // Добавляем CSS для разных стилей рамок
    if (frameStyle !== 'native') {
      const styleId = 'frame-style-css';
      let existingStyle = document.getElementById(styleId);

      if (existingStyle) {
        existingStyle.remove();
      }

      let frameCSS = '';

      if (frameStyle === 'minimal') {
        frameCSS = `
          [data-frame-style="minimal"] {
            --frame-bg: #f5f5f5;
            --frame-border: #ddd;
          }
          [data-frame-style="minimal"] html {
            border: 1px solid var(--frame-border);
          }
        `;
      } else if (frameStyle === 'dark') {
        frameCSS = `
          [data-frame-style="dark"] {
            --frame-bg: #2d3d50;
            --frame-color: #fff;
          }
          [data-frame-style="dark"] html,
          [data-frame-style="dark"] body {
            background-color: #2d3d50;
            color: #fff;
          }
          [data-frame-style="dark"] html {
            border-top: 4px solid #1a2332;
          }
        `;
      } else if (frameStyle === 'light') {
        frameCSS = `
          [data-frame-style="light"] {
            --frame-bg: #ffffff;
            --frame-border: #e0e0e0;
          }
          [data-frame-style="light"] html {
            border: 2px solid var(--frame-border);
            box-shadow: inset 0 0 0 1px var(--frame-border);
          }
        `;
      } else if (frameStyle === 'blue') {
        frameCSS = `
          [data-frame-style="blue"] {
            --frame-bg: #3699d9;
            --frame-color: #fff;
          }
          [data-frame-style="blue"] html {
            border-top: 5px solid #3699d9;
            border-left: 2px solid #3699d9;
            border-right: 2px solid #3699d9;
          }
          [data-frame-style="blue"] html::before {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, #3699d9 0%, #2d8bc9 100%);
            z-index: 10000;
            pointer-events: none;
          }
        `;
      }

      if (frameCSS) {
        const style = document.createElement('style');
        style.id = styleId;
        style.textContent = frameCSS;
        document.head.appendChild(style);
      }
    }
  }
});

window.addEventListener('DOMContentLoaded', () => {
  // Добавляем класс, что запущено в Electron
  document.documentElement.classList.add('electron-app');

  // Показываем версию в title если не задана
  if (!document.title) {
    document.title = 'FixByte CRM';
  }
});
